rret = max(rret, texture(sampler_noise_hq, uv*.165 + 0.03*vec2(cos(uv.y*(10+10*sin(q11))-q1),sin(uv.x * 10.0+q2) + 2.0*q11)));
rret /= max(rret, texture(sampler_noise_hq, uv * 2.0 + 0.03*vec2(cos(uv.y*(20+10*cos(q11))+q3),sin(uv.x * 27.0-q4) + 2.0*q13)));
float mrret=1.2*rret-(.8*rret.yzx);
//rret*=vec3(.9+.5*q14,.9+.5*q15,.9+.5*q16);
ret=min(max(rret.x,mrret),max(rret.z,mrret));
ret-=mix(GetBlur3(uv), min(rret.yzx,mrret.xxx),.25);
ret.g+=.45*q8*mix(rret.y,mrret,.5);
ret.b+=.45*q7*mix(rret.z,mrret,.5);
ret.r+=.45*q6*mix(rret.x,mrret,.5);
ret*=vec3(.9+.05*q14,.9+.05*q15,.9+.05*q16);
}

